 note='Final Pass 03/07 remediation: expanded C2 Unit 10 zero-new-target capstone into the 700–1200-word production band with cross-domain argument reconstruction, explicit counterevidence, calibrated uncertainty, and reviewable judgment.';notes=r.setdefault('quality',{}).setdefault('notes',[])
 if note not in notes:notes.append(note)
 assert 700<=r['word_count']<=1200,(pid,r['word_count']);assert r.get('new_lexical_targets')==[],pid
