 assert len(r['questions'])==10 and len(r['answer_key'])==10,pid
 for q in r['questions']:assert not q.get('target_ids'),(pid,q['id'],q.get('target_ids'))
 types=[q['type'] for q in r['questions']];assert sum(t in COMP for t in types)>=4,(pid,'comp',types);assert sum(t in LEX for t in types)>=2,(pid,'lex',types);assert sum(t in GRAM for t in types)>=2,(pid,'gram',types);assert sum(t in SYN for t in types)>=1,(pid,'syn',types)
